Human: <transcript>
{"user":"Do something very simple for me write a lua script to call yinctl --img ~/.config/hypr/wallpaper/gojo-eye.mp4 when a new monitor is added by socat -U - UNIX-CONNECT:$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/.socket2.sock | grep --line-buffered monitoradded"}
{"Write":"/home/krubics/monitor-wallpaper.lua: #!/usr/bin/env lua

local runtime_dir = os.getenv("XDG_RUNTIME_DIR")
local sig = os.getenv("HYPRLAND_INSTANCE_SIGNATURE")

if not runtime_dir or not sig then
  io.stderr:write("XDG_RUNTIME_DIR or HYPRLAND_INSTANCE_SIGNATURE not set\n")
  os.exit(1)
end

local socket = runtime_dir .. "/hypr/" .. sig .. "/.socket2.sock"
local cmd = "socat -U - UNIX-CONNECT:" .. socket

local handle = io.popen(cmd, "r")
if not handle then
  io.stderr:write("Failed to connect to Hyprland socket\n")
  os.exit(1)
end

for line in handle:lines() do
  if line:match("^monitoradded") then
    os.execute("yinctl --img ~/.config/hypr/wallpaper/gojo-eye.mp4")
  end
end

handle:close()
"}
