if not runtime_dir or not sig then
  io.stderr:write("XDG_RUNTIME_DIR or HYPRLAND_INSTANCE_SIGNATURE not set\n")
  os.exit(1)
end

local socket = runtime_dir .. "/hypr/" .. sig .. "/.socket2.sock"
local cmd = "socat -U - UNIX-CONNECT:" .. socket

