{"Edit":{"file_path":"/home/krubics/monitor-wallpaper.lua","adds":"for line in handle:lines() do
  local monitor = line:match("^monitoradded>>(.+)")
  if monitor then
    -- Kill any running yinctl so it drops its stale monitor state
    os.execute("pkill -x yinctl 2>/dev/null; sleep 0.5")

    -- Ask Hyprland for the current monitor list and send to each one.
    -- This avoids trusting the potentially-stale name from the event or
    -- from yinctl's internal cache.
    local mh = io.popen("hyprctl monitors -j | grep -oP '\"name\":\\s*\"\\K[^\"]+' 2>/dev/null")
    if mh then
